{{-- One token of a chat message (streamChat.js tokenize()): text, link or NIP-30 emoji. Text is always x-text, never HTML. --}}
<span class="contents"><span x-show="token.type === 'text'" x-text="token.type === 'text' ? token.value : ''"></span><a x-show="token.type === 'link'" :href="token.type === 'link' ? token.url : null" x-text="token.type === 'link' ? token.value : ''" target="_blank" rel="noopener noreferrer nofollow ugc" class="[overflow-wrap:anywhere] text-btc underline decoration-btc/40 underline-offset-2 hover:text-btc-hi"></a><img x-show="token.type === 'emoji'" :src="token.type === 'emoji' ? token.url : null" :alt="':' + token.value + ':'" :title="':' + token.value + ':'" referrerpolicy="no-referrer" loading="lazy" data-test="live-chat-emoji-img" class="inline-block h-[1.5em] w-auto max-w-[4em] align-[-0.4em] object-contain"></span>
